/** 单个预警标签：圆角 12dp + 半透明底（#AARRGGBB）+ 同色粗体字；flash 时无限透明度闪烁。 */
@Composable
fun SublAlertTag(text: String, bg: Color, fg: Color, flash: Boolean = false) {
    Box(
        Modifier
            .sublClip(12)
            .background(bg)
            .padding(horizontal = 12.dp, vertical = 5.dp)
            .then(if (flash) Modifier.flash() else Modifier),
    ) {
        Text(text, fontSize = 13.sp, fontWeight = FontWeight.Bold, color = fg)
    }
}

