            Spacer(Modifier.height(12.dp))
            Text("药物", fontSize = 14.sp, color = MaterialTheme.colorScheme.onSurfaceVariant)
            Spacer(Modifier.height(6.dp))
            // **动态药物行**：forEachIndexed 生成，回调 key 带 index —— 点哪行选哪行（旧协议 §6 串点击 bug 消失）
            LazyColumn(Modifier.fillMaxWidth().height(168.dp), verticalArrangement = Arrangement.spacedBy(6.dp)) {
                items(drugs.size) { index ->
                    val name = drugs[index]
                    val selected = pick == index
                    Card(
                        modifier = Modifier.fillMaxWidth().clickable {
                            DshComposeHost.callJs(CB_PICK + "_" + index, "[]")
                        },
                        colors = CardDefaults.cardColors(
                            containerColor = if (selected) Palette.primaryContainer else MaterialTheme.colorScheme.surfaceVariant,
                        ),
