            Spacer(Modifier.height(12.dp))
            OutlinedTextField(
                value = doseText,
                onValueChange = {
                    doseText = it
                    DshComposeHost.callJs(CB_DOSE_CHANGE, "[" + JSONStr(it) + "]")
                },
                label = { Text("剂量 (mg)") },
                singleLine = true,
                keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
                modifier = Modifier.fillMaxWidth(),
            )
            Spacer(Modifier.height(16.dp))
            Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.End) {
                TextButton(onClick = { DshComposeHost.callJs(CB_SHEET_CANCEL, "[]") }) { Text("取消") }
                Spacer(Modifier.size(8.dp))
                Button(onClick = { DshComposeHost.callJs(CB_SHEET_CONFIRM, "[]") }) { Text("确认") }  // 四级校验在 JS
            }
        }
