// —— 值映射（契约 §4.1）：结构体 / 列表 / 标量 ——
data class MedCard(val name: String, val time: String, val route: String, val dose: String)

private fun parseRecs(o: org.json.JSONObject): List<MedCard> {
    val arr = o.optJSONArray("v") ?: return emptyList()
    val out = ArrayList<MedCard>(arr.length())
    for (i in 0 until arr.length()) {
        val r = arr.optJSONObject(i) ?: continue
        out += MedCard(r.optString("name"), r.optString("time"), r.optString("route"), r.optString("dose"))
    }
    return out
}
private fun parseFloats(o: org.json.JSONObject): List<Float> {
    val arr = o.optJSONArray("v") ?: return emptyList()
    return (0 until arr.length()).map { arr.optDouble(it).toFloat() }
}
private fun parseStrings(o: org.json.JSONObject): List<String> {
    val arr = o.optJSONArray("v") ?: return emptyList()
    return (0 until arr.length()).map { arr.optString(it) }
}
private fun parseSeries(o: org.json.JSONObject): List<SublSeries> {
    val arr = o.optJSONArray("v") ?: return emptyList()
    val out = ArrayList<SublSeries>(arr.length())
    for (i in 0 until arr.length()) {
        val s = arr.optJSONObject(i) ?: continue
        val pts = s.optJSONArray("points") ?: continue
        out += SublSeries(
            label = s.optString("label"),
            color = colorOf(s.optString("color")),
            points = (0 until pts.length()).map { pts.optDouble(it).toFloat() },
        )
    }
    return out
}

private fun barColorOf(drug: String): Color =
    if (drug == "氟伏沙明" || drug == "帕罗西汀" || drug == "舍曲林" || drug == "氟西汀") Palette.ssri else Palette.defaultBar

private fun drugDetailOf(name: String): String =
    when (name) {
        "氟伏沙明" -> "SSRI · T½ 15h · F=50% · 口服"
        "帕罗西汀" -> "SSRI · T½ 21h · F=50% · 口服"
        else -> "SSRI · 口服"
    }

private fun JSONStr(s: String): String =
    org.json.JSONObject.quote(s)

